//! Exactly two individual class arguments in a grouped not list.
use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn browser_rank_color8(){let h=include_str!("fixtures/not_class_pair_cascade.html");let t=kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],&Limits::DEFAULT,None,SupplyBudget::CANONICAL,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0x0000ff,0x0000ff,0x0000ff,0xff0000,0x0000ff,0x0000ff,0x0000ff]);}
#[test] fn original2_four_combinations(){let text=include_str!("fixtures/not_class_pair_original2.txt");let mut n=0;for q in text.lines(){let level=if q.contains("\"3\""){3}else{4};for(c,w)in[("",0xff0000),("ot-host-name",0),("ot-host-desc",0),("ot-host-name ot-host-desc",0),("OT-HOST-NAME",0xff0000),("ot-host-nameX",0xff0000),("ot-host-name&#160;ot-host-desc",0xff0000),("x&#9;ot-host-desc",0)]{let b=format!("<div id=onetrust-pc-sdk><ul><li><p aria-level={level} class='{c}'>x</p></li></ul></div>");let t=run(&format!("{q}{{color:red}}"),&b,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="p").unwrap().style.color,w,"{q} {c}");}n+=1;println!("NOT-PAIR-PUBLIC original={} fourcombinations=true tokencontrols=true",n);}assert_eq!(n,2);}
#[test] fn global_work_and_partial_attribute_tree(){let b=format!("<div class='{}'></div>","a ".repeat(100));let q=":not(.x,.y){color:red}";assert!(!run(q,&b,&Limits::DEFAULT,&snap()).truncated);let t=run(&q.repeat(100),&b.repeat(200),&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let long=format!("<div class='{}'></div>","a ".repeat(1000));let t=run(":not(.x,.y):not(.x,.y){color:red}",&long,&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let b=format!("<div {} class=a></div>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(":not(.a,.b){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.diagnostics.dropped_attributes>0&&t.truncated);assert!(!t.unsupported,"enrolled but partialdiagnostictree");}
#[test] fn state_dependency_and_partial_isolation(){let q=":not(.a,.b):where(:not(:focus)){color:red}";let mut s=snap();assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);assert!(run(q,"<div autofocus></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("x".into()));let t=run(":not(.a,.b):target{color:red}","<div id=x></div>",&Limits::DEFAULT,&s);assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);for l in [Limits{max_input_bytes:30,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(":not(.a,.b){color:red}","<div>text</div>",&l,&snap());assert!(t.unsupported||t.truncated);}let h=b"<!doctype html><style>:not(.a,.b){color:red}</style><div></div>";assert!(kobo_web_document::parse_style_tree(h,&[],&Limits::DEFAULT).unsupported);}
#[test] fn sixteen_logical_members_seventeen_refuses_and_legacy_other_commas(){for(n,bad)in[(16,false),(17,true)]{let q=vec![":not(.a,.b)";n].join(",");let t=run(&format!("{q}{{color:red}}"),"<div class=c></div>",&Limits::DEFAULT,&snap());assert_eq!(t.unsupported,bad);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::CssSelectorGroup)>0,bad);}for q in [r#"[data-x="a,b"]"#,r#"[data-x="v,:not(.a,.b)"]"#,r#":not(.a,.b)[data-x="a,b"]"#,":not(.a,.b,.c)",":not(.a,#x)"]{assert!(run(&format!("{q}{{color:red}}"),"<div data-x='a,b'></div>",&Limits::DEFAULT,&snap()).unsupported);}let t=run(".good,:not(.a,.b,.c){color:red}","<div class=good></div>",&Limits::DEFAULT,&snap());assert!(t.unsupported);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000,"legacy diagnostic partialbranch policy retained");}
